{"command": "cd /workspace && cat <<'EOF' > app.py
from __future__ import annotations

from dataclasses import dataclass, field, asdict
from datetime import date, datetime
from typing import Any, Dict, List, Optional
from flask import Flask, jsonify, request

app = Flask(__name__)

ROLES = {"admin", "office", "teacher", "parent"}


def iso_now() -> str:
    return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"


@dataclass
class Family:
    id: int
    name: str
    contacts: List[Dict[str, Any]] = field(default_factory=list)
    children: List[int] = field(default_factory=list)


@dataclass
class Child:
    id: int
    family_id: int
    name: str
    age_group: str
    health_info: Dict[str, Any] = field(default_factory=dict)
    immunizations: Dict[str, Any] = field(default_factory=dict)
    enrollment_status: str = "pending"
    classroom: Optional[str] = None
    waiting_list_position: Optional[int] = None


@dataclass
class Classroom:
    id: str
    age_group: str
    capacity: int
    enrolled_child_ids: List[int] = field(default_factory=list)


@dataclass
class Invoice:
    id: int
    family_id: int
    child_id: int
    amount: float
    description: str
    paid: float = 0.0

    @property
    def outstanding(self) -> float:
        return round(self.amount - self.paid, 2)


families: Dict[int, Family] = {}
children: Dict[int, Child] = {}
classrooms: Dict[str, Classroom] = {}
waiting_lists: Dict[str, List[int]] = {}
invoices: Dict[int, Invoice] = {}
audit_log: List[Dict[str, Any]] = []
next_ids = {"family": 1, "child": 1, "invoice": 1}


def log_action(actor: str, action: str, details: Dict[str, Any]) -> None:
    audit_log.append({"timestamp": iso_now(), "actor": actor, "action": action, "details": details})


def require_role(*allowed: str):
    role = request.headers.get("X-Role", "office")
    if role not in ROLES:
        return None, (jsonify({"error": "invalid role"}), 400)
    if allowed and role not in allowed:
        return None, (jsonify({"error": "forbidden"}), 403)
    return role, None


def check_access_for_family(role: str, family_id: int):
    if role in {"admin", "office"}:
        return None
    if role == "parent":
        try:
            allowed_family = int(request.headers.get("X-Family-Id", "-1"))
        except ValueError:
            allowed_family = -1
        if allowed_family != family_id:
            return (jsonify({"error": "forbidden"}), 403)
    return None


@app.get("/health")
def health():
    return jsonify({"status": "ok"})


@app.post("/setup/classrooms")
def setup_classrooms():
    role, err = require_role("admin", "office")
    if err:
        return err
    data = request.get_json(force=True)
    classroom = Classroom(id=data["id"], age_group=data["age_group"], capacity=int(data["capacity"]))
    classrooms[classroom.id] = classroom
    waiting_lists.setdefault(classroom.age_group, [])
    log_action(role, "upsert_classroom", asdict(classroom))
    return jsonify(asdict(classroom)), 201


@app.post("/families")
def create_family():
    role, err = require_role("admin", "office")
    if err:
        return err
    data = request.get_json(force=True)
    fid = next_ids["family"]
    next_ids["family"] += 1
    fam = Family(id=fid, name=data["name"], contacts=data.get("contacts", []))
    families[fid] = fam
    log_action(role, "create_family", asdict(fam))
    return jsonify(asdict(fam)), 201


@app.post("/children")
def create_child():
    role, err = require_role("admin", "office")
    if err:
        return err
    data = request.get_json(force=True)
    family_id = int(data["family_id"])
    if family_id not in families:
        return jsonify({"error": "family not found"}), 404
    cid = next_ids["child"]
    next_ids["child"] += 1
    child = Child(id=cid, family_id=family_id, name=data["name"], age_group=data["age_group"],
                  health_info=data.get("health_info", {}), immunizations=data.get("immunizations", {}),
                  enrollment_status=data.get("enrollment_status", "pending"))
    children[cid] = child
    families[family_id].children.append(cid)
    if child.enrollment_status == "waiting":
        waiting_lists.setdefault(child.age_group, []).append(cid)
        child.waiting_list_position = len(waiting_lists[child.age_group])
    log_action(role, "create_child", asdict(child))
    return jsonify(asdict(child)), 201


@app.get("/enrollment/summary")
def enrollment_summary():
    role, err = require_role("admin", "office", "teacher")
    if err:
        return err
    enrolled = [asdict(c) for c in children.values() if c.enrollment_status == "enrolled"]
    pending = [asdict(c) for c in children.values() if c.enrollment_status == "pending"]
    waiting = [asdict(c) for c in children.values() if c.enrollment_status == "waiting"]
    return jsonify({"enrolled": enrolled, "pending": pending, "waiting": waiting})


@app.get("/classrooms/availability")
def classroom_availability():
    role, err = require_role("admin", "office", "teacher")
    if err:
        return err
    result = []
    for c in classrooms.values():
        result.append({
            "id": c.id,
            "age_group": c.age_group,
            "capacity": c.capacity,
            "enrolled": len(c.enrolled_child_ids),
            "open_spots": max(c.capacity - len(c.enrolled_child_ids), 0),
        })
    return jsonify(result)


@app.post("/waiting-list/<age_group>/next")
def next_waiting(age_group: str):
    role, err = require_role("admin", "office")
    if err:
        return err
    q = waiting_lists.get(age_group, [])
    if not q:
        return jsonify({"next_child_id": None})
    cid = q[0]
    return jsonify({"next_child_id": cid, "child": asdict(children[cid])})


@app.post("/waiting-list/<int:child_id>/enroll")
def enroll_from_waiting(child_id: int):
    role, err = require_role("admin", "office")
    if err:
        return err
    child = children.get(child_id)
    if not child:
        return jsonify({"error": "child not found"}), 404
    open_classroom = None
    for classroom in classrooms.values():
        if classroom.age_group == child.age_group and len(classroom.enrolled_child_ids) < classroom.capacity:
            open_classroom = classroom
            break
    if not open_classroom:
        return jsonify({"error": "no capacity"}), 409
    if child.waiting_list_position and child_id in waiting_lists.get(child.age_group, []):
        waiting_lists[child.age_group].remove(child_id)
        for idx, cid in enumerate(waiting_lists[child.age_group], start=1):
            children[cid].waiting_list_position = idx
    child.enrollment_status = "enrolled"
    child.classroom = open_classroom.id
    child.waiting_list_position = None
    open_classroom.enrolled_child_ids.append(child_id)
    log_action(role, "enroll_child", {"child_id": child_id, "classroom": open_classroom.id})
    return jsonify(asdict(child))


@app.post("/billing/generate")
def generate_billing():
    role, err = require_role("admin", "office")
    if err:
        return err
    data = request.get_json(force=True)
    family_id = int(data["family_id"])
    child_id = int(data["child_id"])
    amount = float(data["amount"])
    invoice_id = next_ids["invoice"]
    next_ids["invoice"] += 1
    inv = Invoice(id=invoice_id, family_id=family_id, child_id=child_id, amount=amount,
                  description=data.get("description", "care charge"))
    invoices[invoice_id] = inv
    log_action(role, "generate_invoice", asdict(inv))
    return jsonify({**asdict(inv), "outstanding": inv.outstanding}), 201


@app.get("/billing/summary")
def billing_summary():
    role, err = require_role("admin", "office")
    if err:
        return err
    rows = [{**asdict(i), "outstanding": i.outstanding} for i in invoices.values()]
    return jsonify(rows)


@app.get("/billing/family/<int:family_id>/statement")
def family_statement(family_id: int):
    role, err = require_role("admin", "office", "parent")
    if err:
        return err
    access = check_access_for_family(role, family_id)
    if access:
        return access
    rows = [{**asdict(i), "outstanding": i.outstanding} for i in invoices.values() if i.family_id == family_id]
    return jsonify({"family_id": family_id, "invoices": rows})


@app.get("/health/reminders")
def health_reminders():
    role, err = require_role("admin", "office", "teacher")
    if err:
        return err
    reminders = []
    for child in children.values():
        current = child.immunizations.get("current", False)
        reminders.append({"child_id": child.id, "child_name": child.name,
                          "health_current": bool(child.health_info),
                          "immunizations_current": current,
                          "needs_attention": (not child.health_info) or (not current)})
    return jsonify(reminders)


@app.get("/report/daily-snapshot")
def daily_snapshot():
    role, err = require_role("admin", "office", "teacher")
    if err:
        return err
    return jsonify({
        "date": date.today().isoformat(),
        "enrollment_counts": {
            "enrolled": len([c for c in children.values() if c.enrollment_status == "enrolled"]),
            "pending": len([c for c in children.values() if c.enrollment_status == "pending"]),
            "waiting": len([c for c in children.values() if c.enrollment_status == "waiting"]),
        },
        "classroom_occupancy": [{"id": c.id, "enrolled": len(c.enrolled_child_ids), "capacity": c.capacity} for c in classrooms.values()],
        "waiting_list": {k: v[:] for k, v in waiting_lists.items()},
        "open_spots": [{"id": c.id, "age_group": c.age_group, "open_spots": max(c.capacity - len(c.enrolled_child_ids), 0)} for c in classrooms.values()],
        "unpaid_invoices": [{"id": i.id, "outstanding": i.outstanding} for i in invoices.values() if i.outstanding > 0],
    })


@app.get("/audit")
def audit_view():
    role, err = require_role("admin", "office")
    if err:
        return err
    q = request.args.get("q", "").lower()
    results = [entry for entry in audit_log if q in str(entry).lower()]
    return jsonify(results)


@app.get("/")
def index():
    return jsonify({"name": "Nenios Child Care Management", "status": "running"})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000, debug=False)
EOF"}

